  args: {
    article: mockArticle,
  },
  play: async ({ canvas }) => {
    await expect(
      canvas.getByRole('heading', { name: /solar system/i }),
    ).toBeVisible();
    await expect(canvas.getByText(/gravitationally bound/i)).toBeVisible();
    await expect(canvas.getByText('Read more →')).toBeVisible();
  },
};

